import sys
from collections import deque

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    n = int(next(iterator))

    adj = [[] for _ in range(n + 1)]
    for _ in range(n - 1):
        u = int(next(iterator))
        v = int(next(iterator))
        w = int(next(iterator))
        adj[u].append((v, w))
        adj[v].append((u, w))

    s = int(next(iterator))
    m = int(next(iterator))
    criminals = []
    for _ in range(m):
        criminals.append(int(next(iterator)))

    def bfs_distances(start_node):
        dist = [-1] * (n + 1)
        dist[start_node] = 0
        queue = deque([start_node])

        while queue:
            u = queue.popleft()
            for v, w in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + w
                    queue.append(v)
        return dist

    dist_s = bfs_distances(s)

    safe_nodes = []
    for v in range(1, n + 1):
        if dist_s[v] != -1:
            for c in criminals:
                dist_c = bfs_distances(c)[v]
                if dist_c < dist_s[v]:
                    break
            else:
                safe_nodes.append(v)

    if not safe_nodes:
        print("Terrorists win")
        return

    dist_s_safe = [dist_s[v] for v in safe_nodes]
    safe_indices = {v: i for i, v in enumerate(safe_nodes)}

    k = len(safe_nodes)
    dist_matrix = [[0] * k for _ in range(k)]

    for i in range(k):
        u = safe_nodes[i]
        d_u = bfs_distances(u)
        for j in range(k):
            v = safe_nodes[j]
            dist_matrix[i][j] = d_u[v]

    INF = float('inf')
    dp = [[INF] * (1 << k) for _ in range(k)]

    for i in range(k): if dist_s_safe[i] < INF:
        dp[i][1 << i] = dist_s_safe[i]

    for mask in range(1, 1 << k):
        for last in range(k):
            if not (mask & (1 << last)):
                continue
            if dp[last][mask] == INF:
                continue

            for nxt in range(k):
                if mask & (1 << nxt):
                    continue
                new_mask = mask | (1 << nxt)
                new_time = dp[last][mask] + dist_matrix[last][nxt]
                if new_time < dp[nxt][new_mask]:
                    dp[nxt][new_mask] = new_time

    full_mask = (1 << k) - 1
    ans = INF
    for i in range(k):
        if dp[i][full_mask] < ans:
            ans = dp[i][full_mask]

    if ans == INF:
        print("Terrorists win")
    else:
        print(ans)

if __name__ == "__main__":
    main()
